	committed  map[string]int        // key -> committed offset (max offset seen)
	maxOffsets map[string]int        // key -> maximum offset used

	mu         sync.RWMutex
}

type LogEntry struct {
	Offset int
	Value  int
}

// Cluster handles coordination between nodes for log consistency
type Cluster struct {
	sync.RWMutex
	nodes      []string
	nodeToMemberID map[string]int // node ID -> member ID in lin-kv (0-indexed)

	logsMu     sync.RWMutex
	linLogs    map[int][]LogEntry  // lin-log index -> entries for all nodes combined
