type PollRequest struct {
	Offsets map[string]int `json:"offsets"`
}

// PollOKReply represents a poll_ok message
type PollOKReply struct {
	Msgs map[string][][2]int `json:"msgs"`
}

// CommitOffsetsRequest represents a commit_offsets message
type CommitOffsetsRequest struct {
	Offsets map[string]int `json:"offsets"`
}

// CommitOffsetsOKReply represents a commit_offsets_ok message
type CommitOffsetsOKReply struct{}

// ListCommittedOffsetsRequest represents a list_committed_offsets message
type ListCommittedOffsetsRequest struct {
	Keys []string `json:"keys"`
}

// ListCommittedOffsetsOKReply represents the reply
type ListCommittedOffsetsOKReply struct {
	Offsets map[string]int `json:"offsets"`
}

func main() {
	node, err := maelstrom.NewNode()
	if err != nil {
		log.Fatalf("Failed to create node: %v", err)
	}

	// Handle init message to get cluster topology
	initReq := &maelstrom.NodeMessage{}
	var reqBytes []byte
	err = node.Handle(&initReq, func(msg *json.RawMessage) error {
		if len(msg.Bytes()) == 0 {
			return nil
		}

		// Check for init command
		type InitReq struct {
			NodeID       string `json:"node_id"`
			OtherNodes   []string `json:"other_nodes"`
		}
		var req InitReq
		err := json.Unmarshal(msg.Bytes(), &req)
		if err != nil {
			return err
		}

		nodeID := req.NodeID
		for _, n := range req.OtherNodes {
			nodes = append(nodes, n)
		}
		nodes = append(nodes, nodeID)

		// Set up cluster coordination - use lin-kv for consensus
		clusters[nodeID] = &Cluster{
			nodeToMemberID: map[string]int{nodeID: len(nodes)-1},
			logsMu: sync.RWMutex{},
			linLogs: make(map[int][]LogEntry),
		}

		// Start the lin-kv node
		lkv, err = maebstrom.NewLinKV(node)
		if err != nil {
			return fmt.Errorf("Failed to create lin-kv: %v", err)
		}

		node.lk = lkv
		node.cluster = clusters[nodeID]

		return nil
	})

	if err != nil {
		log.Fatalf("Handle error: %v", err)
	}

	err = node.Run()
	if err != nil {
		log.Fatal(err)
