package main

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"os"
	"sync"
	"time"

	"github.com/jepsen-io/maelstrom/demo/go"
)

// Node handles requests from clients and communicates with other nodes
type Node struct {
	nodeID  string
	nodes   []string
	nk      *go.Node
	lkv     *go.LinKV
	cluster *Cluster

	// My local logs (key -> [offsets used, max_offset])
	myLogs    map[string][]LogEntry
	maxOffsets map[string]int

	// Global max offsets for this node's view of each log
	globalMaxOffsets map[string]int

	mu         sync.RWMutex
}

type LogEntry struct {
	Offset int
	Value  int
}

// Cluster handles coordination between nodes for log consistency using lin-kv
type Cluster struct {
	nodes      []string
	nodeToMemberID map[string]int // node ID -> member ID (0-indexed)

	// Each node has its own lin-log, but we coordinate via lin-kv to agree on global max
	linLogIndices map[int]int  // node index -> offset in lin-log at which it last committed

	logsMu    sync.RWMutex
	globalMax map[string]int   // key -> maximum offset seen by any node

	// For replication: each node stores what logs it has fully replicated
	replicated map[int]map[string][]LogEntry // lin-log index -> node index -> log entries
}

func main() {
	// Initialize using maelstrom's framework
	node, err := go.NewNode()
	if err != nil {
		log.Fatalf("Failed to create node: %v", err)
	}

	var nodes []string
	err = node.Handle(&struct{}{}, func(msg *json.RawMessage) error {
		if len(msg.Bytes()) == 0 || msg.Len() < 1 {
			return nil
		}

		type InitReq struct {
			NodeID      string `json:"node_id"`
			OtherNodes  []string `json:"other_nodes"`
		}
		var req InitReq
		err := json.Unmarshal(msg.Bytes(), &req)
		if err != nil {
			return err
		}

		nodeID := req.NodeID
		for _, n := range req.OtherNodes {
			nodes = append(nodes, n)
		}
		nodes = append(nodes, nodeID)

		return nil
	})
	if err != nil {
		log.Fatalf("Handle init error: %v", err)
	}

	err = node.Run()
	if err != nil {
		log.Fatal(err)
	}
}

// handleSend handles send messages
func (n *Node) handleSend(msg json.RawMessage) error {
	var req struct {
		Key   string `json:"key"`
		Value int    `json:"msg"`
	}
	err := json.Unmarshal(msg, &req)
	if err != nil {
		return fmt.Errorf("parse send: %v", err)
	}

	n.mu.Lock()

	// Generate offset based on our local log state
	var newOffset int
	localLog, ok := n.myLogs[req.Key]
	if !ok {
		// New log
		newOffset = 1000 + len(nodes)-1
	} else {
		// Find max offset
		offsetsSeen := make(map[int]bool)
		for _, e := range localLog {
			offsetsSeen[e.Offset] = true
			if e.Offset > n.globalMaxOffsets[req.Key] {
				n.globalMaxOffsets[req.Key] = e.Offset
			}
		}
		newOffset = offsetsSeen[len(offsetsSeen)-1] + 1
		if newOffset < n.globalMaxOffsets[req.Key]+1000 {
			newOffset = n.globalMaxOffsets[req.Key]
		} else {
			newOffset = offsetsSeen[len(offsetsSeen)-1] + 1
		}
	}

	// Append entry to local log
	n.myLogs[req.Key] = append(n.myLogs[req.Key], LogEntry{Offset: newOffset, Value: req.Value})

	n.mu.Unlock()

	// Use lin-kv for cross-node coordination via CompareAndSwap
	ctx := context.Background()
	nodeIndex := len(nodes) - 1
	keyVal := []byte(fmt.Sprintf("%d:%s", nodeIndex, req.Key))

	// Check if this entry is already replicated elsewhere
	// If not, we need to wait for consensus or replicate ourselves

	reply := &struct {
		InReplyTo uint32 `json:"in_reply_to"`
		Offset    int    `json:"offset"`
	}{}

	// For simplicity: use a simpler approach - just use our local log and broadcast via lin-kv
	// The key insight: lin-kv provides linearizable reads, so we can use it to coordinate

	// Check if we have a replica from another node for this entry
	replicas, err := n.lkv.Read(ctx, keyVal)
	if err != nil {
		log.Printf("lin-kv Read error: %v", err)
	}

	// Store offset with a unique marker per (node, key, offset)
	offsetMarker := fmt.Sprintf("%d:%s:%d", nodeIndex, req.Key, newOffset)

	n.lkv.Write(ctx, []byte(offsetMarker))

	return nil
}

// handleSendOK handles send_ok responses
func (n *Node) handleSendOK(msg json.RawMessage) error {
	var rep struct {
		InReplyTo uint32 `json:"in_reply_to"`
		Offset    int    `json:"offset"`
	}
	err := json.Unmarshal(msg, &rep)
	if err != nil {
		return fmt.Errorf("parse send_ok: %v", err)
	}
	return nil
}

// handlePoll handles poll messages - reads from multiple logs at given offsets
func (n *Node) handlePoll(msg json.RawMessage) error {
	var req struct {
		Offsets map[string]int `json:"offsets"`
	}
	err := json.Unmarshal(msg, &req)
	if err != nil {
		return fmt.Errorf("parse poll: %v", err)
	}

	n.mu.Lock()

	result := make(map[string][][2]int)
	for key, offset := range req.Offsets {
		logs, ok := n.myLogs[key]
		var entries [][2]int
		if !ok || offset > logs[len(logs)-1].Offset {
			continue // log exhausted at this offset
		}

		// Start from the requested offset or after it
		for _, e := range logs {
			if e.Offset < offset {
				continue
			}
			entries = append(entries, [2]int{e.Offset, e.Value})
		}
		result[key] = entries
	}

	n.mu.Unlock()

	reply := &struct {
		InReplyTo uint32 `json:"in_reply_to"`
		Msgs      map[string][][2]int `json:"msgs"`
	}{
		Msgs: result,
	}
	return json.Marshal(reply)
}

// handleCommitOffsets handles commit_offsets messages
func (n *Node) handleCommitOffsets(msg json.RawMessage) error {
	var req struct {
		Offsets map[string]int `json:"offsets"`
	}
	err := json.Unmarshal(msg, &req)
	if err != nil {
		return fmt.Errorf("parse commit_offsets: %v", err)
	}

	n.mu.Lock()
	for key, offset := range req.Offsets {
		n.committed[key] = offset
		if offset > n.globalMaxOffsets[key] {
			n.globalMaxOffsets[key] = offset
		}
	}

	// Update lin-kv to reflect committed state
	offsetMarker := fmt.Sprintf("committed:%s", n.nodeID)
	for key, offset := range req.Offsets {
		offsetMarker += fmt.Sprintf("%s=%d;", key, offset)
	}
	n.lkv.Write(context.Background(), []byte(offsetMarker))

	n.mu.Unlock()

	reply := &struct {
		InReplyTo uint32 `json:"in_reply_to"`
	}{
		_: 1,
	}
	return json.Marshal(reply)
}

// handleListCommittedOffsets handles list_committed_offsets messages
func (n *Node) handleListCommittedOffsets(msg json.RawMessage) error {
	var req struct {
		Keys []string `json:"keys"`
	}
	err := json.Unmarshal(msg, &req)
	if err != nil {
		return fmt.Errorf("parse list: %v", err)
	}

	n.mu.Lock()
	result := make(map[string]int)
	for _, key := range req.Keys {
		offset, ok := n.committed[key]
		if !ok || offset < 1000 { // uncommitted or no commit
			continue
		}
		if offset > n.globalMaxOffsets[key] {
			n.globalMaxOffsets[key] = offset
		}
		result[key] = offset
	}

	offsetMarker := fmt.Sprintf("list:%s", n.nodeID)
	for key, offset := range req.Keys {
		offsetMarker += fmt.Sprintf("%s=%d;", key, offset)
	}
	n.lkv.Write(context.Background(), []byte(offsetMarker))

	n.mu.Unlock()

	reply := &struct {
		InReplyTo uint32 `json:"in_reply_to"`
		Offsets   map[string]int `json:"offsets"`
	}{
		Offset: result,
	}
	return json.Marshal(reply)
}

// handleRPC handles RPC messages to other nodes
func (n *Node) handleRPC(ctx go.Context, dest string, msg json.RawMessage) error {
	src := msg.String() // sender

	var req struct {
		Type     string `json:"type"`
		MsgID    uint32 `json:"msg_id"`
	}
	if err := json.Unmarshal(msg, &req); err != nil {
		return err
	}

	msgType := ""
	switch req.Type {
	case "send":
		msgType = "send"
	case "poll":
		msgType = "poll"
	case "commit_offsets":
		msgType = "commit_offsets"
	case "list_committed_offsets":
		msgType = "list_committed_offsets"
	default:
		return fmt.Errorf("unknown type: %s", req.Type)
	}

	reply, err := n.send(ctx, dest, msgType)
	if err != nil {
		return err
	}

	return json.Marshal(reply)
}

// send sends a message to another node
func (n *Node) send(ctx go.Context, dest string, msgType string) (json.RawMessage, error) {
	var reply interface{}
	switch msgType {
	case "send":
		reply = &struct {
			InReplyTo uint32 `json:"in_reply_to"`
			Offset    int    `json:"offset"`
		}{}
	case "poll":
		reply = &struct {
			InReplyTo uint32 `json:"in_reply_to"`
			Msgs      map[string][][2]int `json:"msgs"`
		}{}
	case "commit_offsets":
		reply = &struct {
			InReplyTo uint32 `json:"in_reply_to"`
		}{}
	case "list_committed_offsets":
		reply = &struct {
			InReplyTo uint32 `json:"in_reply_to"`
			Offsets   map[string]int `json:"offsets"`
		}{}
	default:
		return nil, fmt.Errorf("unknown message type")
	}

	msgBytes, _ := json.Marshal(reply)
	return msgBytes, nil
}

package main

import (
