	"log"
	"os"
	"time"

	"github.com/jepsen-io/maelstrom/demo/go"
)

// Node implements a log coordinator node
type Node struct {
	id   string
	nodes []string

	// My local state
	myLogs       map[string][]LogEntry // key -> [offsets, values]
	maxOffsets   map[string]int        // my local max per key
	committed    map[string]int        // committed offset per key

	// lin-kv for coordination across nodes
	lkv *go.LinKV

	mu sync.RWMutex
}

type LogEntry struct { Offset int; Value int }

func main() {
	node, err := go.NewNode()
	if err != nil {
		log.Fatalf("failed to create node: %v", err)
	}

	err = node.Handle(&struct{}{}, func(msg *json.RawMessage) error {
		if msg == nil || len(*msg) == 0 {
			return nil
		}

		type initMsg struct {
			NodeID      string `json:"node_id"`
			OtherNodes  []string `json:"other_nodes"`
		}
		var req initMsg
		err := json.Unmarshal(*msg, &req)
		if err != nil {
			return err
		}

		node.id = req.NodeID

		// Setup lin-kv for node coordination
		lkvNode, err := go.NewLinKV(node)
		if err != nil {
			log.Printf("lin-kv error: %v", err)
			return err
		}
		node.lkv = lkvNode

		return nil
	})
	if err != nil {
		log.Fatalf("handle init error: %v", err)
	}

