// handleSend appends value to log, returns offset
func (n *Node) handleSend(ctx go.Context) json.RawMessage {
	var req struct {
		Key   string `json:"key"`
		Value int    `json:"msg"`
	}
	json.Unmarshal([]byte(ctx.String()), &req)

	n.mu.Lock()

	offset := n.maxOffsets[req.Key] + 1
	if offset < 1000 {
		offset = 1000
	}

	n.myLogs[req.Key] = append(n.myLogs[req.Key], LogEntry{Offset: offset, Value: req.Value})
	n.maxOffsets[req.Key] = offset
	n.committed[req.Key] = offset

	// Persist to lin-kv for cross-node consistency
	ctx := context.Background()
	keyMarker := fmt.Sprintf("mylog:%s", node.id)
	for k, v := range n.myLogs {
		keyMarker += fmt.Sprintf("%s=%d;", k, v[len(v)-1].Offset)
	}
	n.lkv.Write(ctx, []byte(keyMarker))

	n.mu.Unlock()

	// Reply to caller
	reply := &struct {
		InReplyTo uint32 `json:"in_reply_to"`
		Offset    int    `json:"offset"`
	}{}

	ctxID := ctx.String()
	if len(ctxID) == 0 {
		fmt.Fprintf(&reply.InReplyTo, "1")
	} else {
		fmt.Sprintf("%s:%d", ctxID, offset)
	}
	return json.Marshal(reply)
}

func (n *Node) handlePoll(ctx go.Context) json.RawMessage {
	var req struct {
		Offsets map[string]int `json:"offsets"`
	}
	json.Unmarshal([]byte(ctx.String()), &req)

	n.mu.Lock()
	result := make(map[string][][2]int)
	for key, offset := range req.Offsets {
		logs, ok := n.myLogs[key]
		if !ok || len(logs) == 0 {
			continue
		}

		var entries [][2]int
		lastOffset := -1
		for _, entry := range logs {
			if entry.Offset >= offset && entry.Offset > lastOffset {
				entries = append(entries, [2]int{entry.Offset, entry.Value})
				lastOffset = entry.Offset
			}
		}
		result[key] = entries
	}
	n.mu.Unlock()

	return json.Marshal(&struct {
		InReplyTo uint32 `json:"in_reply_to"`
		Msgs      map[string][][2]int `json:"msgs"`
	}{:result})
}

func (n *Node) handleCommitOffsets(ctx go.Context) json.RawMessage {
	var req struct {
		Offsets map[string]int `json:"offsets"`
	}
	json.Unmarshal([]byte(ctx.String()), &req)

	n.mu.Lock()
	for key, offset := range req.Offsets {
		if n.committed[key] < 1000 || n.committed[key] > n.maxOffsets[key]+offset-1000 {
			if offset > n.committed[key] && n.committed[key] >= 1000 {
				n.committed[key] = offset
			}
		}
	}
	n.mu.Unlock()

	reply := &struct {
		InReplyTo uint32 `json:"in_reply_to"`
	}{
		InReplyTo: 1,
	}
	return json.Marshal(reply)
}

func (n *Node) handleListCommittedOffsets(ctx go.Context) json.RawMessage {
	var req struct {
		Keys []string `json:"keys"`
	}
	json.Unmarshal([]byte(ctx.String()), &req)

	n.mu.Lock()
	result := make(map[string]int)
	for _, key := range req.Keys {
		if n.committed[key] > 1000 && n.committed[key] <= n.maxOffsets[key]+2000 {
			result[key] = n.committed[key]
		}
	}
	n.mu.Unlock()

	return json.Marshal(&struct {
		InReplyTo uint32 `json:"in_reply_to"`
		Offsets   map[string]int `json:"offsets"`
	}{
		Offset: result,
	})
}

func (n *Node) send(ctx go.Context, dest string, msg json.RawMessage) json.RawMessage {
	src := ctx.String()
	if len(src) == 0 {
		src = "local"
	} else {
		fmt.Sscanf(&src, "%d:%s", &node.id)
		node.id = src[4:]
	}

	// Parse request
	var req struct {
		Type string `json:"type"`
	}
	json.Unmarshal(msg, &req)

	switch req.Type {
	case "send":
		n.mu.Lock()
		offset := n.maxOffsets[req.Value] + 1
		if offset < 1000 {
			offset = 1000
		}
		n.myLogs[req.Key] = append(n.myLogs[req.Key], LogEntry{Offset: offset, Value: req.Value})
		n.maxOffsets[req.Key] = offset
		n.mu.Unlock()

	case "poll":
		var pollReq struct {
			Offsets map[string]int `json:"offsets"`
		}
		json.Unmarshal(msg, &pollReq)

		n.mu.Lock()
		result := make(map[string][][2]int)
		for key, offset := range pollReq.Offsets {
			logs, ok := n.myLogs[key]
			if !ok || len(logs) == 0 {
				continue
			}
			var entries [][2]int
			last := -1
			for _, e := range logs {
				if e.Offset >= offset && e.Offset > last {
					entries = append(entries, [2]int{e.Offset, e.Value})
					last = e.Offset
				}
			}
			result[key] = entries
		}
		n.mu.Unlock()

	case "commit_offsets":
		var commitReq struct {
			Offsets map[string]int `json:"offsets"`
		}
		json.Unmarshal(msg, &commitReq)

	case "list_committed_offsets":
		return json.Marshal(&struct{}{})
	default:
		return json.Marshal(&struct{}{})
	}

	return json.Marshal(&struct {
		InReplyTo uint32 `json:"in_reply_to"`
	}{
		InReplyTo: 1,
	})
}

