	maxOffsets   map[string]int        // my max offset per key (this node's view)
	committed    map[string]int        // committed offset (max I know about)

	// lin-kv for cross-node coordination - stores the GLOBAL maximum offset used per key
	lkv *go.LinKV

	// To avoid deadlocks: track what we've written via CAS tokens
	casToken int64

	mu sync.RWMutex
}

type LogEntry struct { Offset int; Value int }

func main() {
	node, err := go.NewNode()
	if err != nil {
		log.Fatalf("failed to create node: %v", err)
