		}
		var req initReq
		json.Unmarshal(*msg, &req)

		node.id = req.NodeID
		nodes := append(req.OtherNodes, node.id)

		lkv, err := go.NewLinKV(node)
		if err != nil {
			log.Printf("lin-kv error: %v", err)
		}
		return nil
	})
