// CAS key for lin-kv coordination per log key
func (n *Node) casKey(key string) []byte {
	return fmt.Sprintf("global-max:%s", key)
}

// handleSend appends value to log, returns offset
func (n *Node) handleSend(ctx go.Context) json.RawMessage {
	var req struct {
		Key   string `json:"key"`
		Value int    `json:"msg"`
	}
	json.Unmarshal([]byte(ctx.String()), &req)

	n.mu.Lock()
	offset := n.maxOffsets[req.Key] + 1
	if offset < 1000 {
		offset = 1000
	}
	n.myLogs[req.Key] = append(n.myLogs[req.Key], LogEntry{Offset: offset, Value: req.Value})
	n.maxOffsets[req.Key] = offset

	n.mu.Unlock()

	// Update lin-kv: check if this node has a higher max, and update it atomically
	ctxCtx := context.Background()
	keyMarker := fmt.Sprintf("max:%s", n.id)
	for k := range n.myLogs {
		kMarker := []byte(k)
		n.lkv.Write(ctxCtx, append([]byte{}, k...)) // unique key per log
	}

	// Use CAS to set the global max for this node's writes
	token := fmt.Sprintf("cas-token:%s", n.id)
	oldVal, err := n.lkv.CompareAndSwap(
		ctxCtx, 
		append([]byte{}, token...), 
		nil, 
		fmt.Sprintf("%d", offset))
	if err != nil {
		log.Printf("CAS error: %v", err)
	}

	reply := &struct {
		InReplyTo uint32 `json:"in_reply_to"`
		Offset    int    `json:"offset"`
	}{
		InReplyTo: uint32(offset),
	}
	return json.Marshal(reply)
}

